entries[396005] = { ["name"] = "Frostbarriere", ["text"] = "20 Meter Reichweite\nKanalisiert (Wirken in 7 tagen)\nErschafft um einen Verbündeten eine Frostbarriere, die (50201 * 3) Schaden absorbiert.\n\nDer Absorptionswert der Barriere erhöht sich 6 Sek. lang alle 3 Sek. zusätzlich um 50201 Schaden, bis zu maximal (50201 * 3 + 50201 * 7) Schaden.\n\nGewährt Immunität gegen Kontrollverlusteffekte." }
