entries[396033] = { ["name"] = "Großer Flammenriss", ["text"] = "300 Meter Reichweite\nSofort\nEranog hüllt sein aktuelles Ziel in Flammen. Bei Ablauf entsteht an der Position des Spielercharakters ein ' Großer Flammenriss ', der Spielercharakteren innerhalb von 6 Metern 65 Feuerschaden zufügt.\n\nAus dem Flammenriss ' stürmt ein Flammenschuppentarasek und hinterlässt ' Lavafluss '." }
