entries[396150] = { ["name"] = "Gefühl der Überlegenheit", ["text"] = "100 Meter Reichweite\nSofort\nDie Gegenwart von Zwietracht gibt Euch ein ' Gefühl der Überlegenheit ', das einerseits Euren verursachten Schaden und die von Euch hervorgerufene Heilung um 25% erhöht, Euch andererseits aber auch alle 2 Sek. 1454670 Schattenschaden zufügt, solange das Gefühl anhält. Der erlittene Schaden ist für jede Sekunde, in der Ihr ein ' Gefühl der Überlegenheit ' habt, um 10% erhöht." }
