entries[396162] = { ["name"] = "Khaz'gorit", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Zeit, in der man Khaz'gorit auf den Dracheninseln einfach an der Oberfläche finden konnte, ist längst vorbei. Minenarbeiter, die nach diesem seltenen Erz suchen, müssen sich mit den kleinen Mengen dieser Ressource zufriedengeben, die manchmal beim Abbauen anderer Metalle entdeckt werden.\nBeruf:\nBergbau (1)" }
entries[396166] = { ["name"] = "Xuens Zorn", ["text"] = "'Comboschläge' gewähren Euch eine stapelbare Chance von 1%, dass Euer nächster Einsatz von 'Furorfäuste' Euch 10 Sek. lang 3% kritischen Trefferwert, Tempo und Meisterschaft gewährt und dabei Xuen den Weißen Tiger beschwört.\n(500ms Abklingzeit)" }
entries[396167] = { ["name"] = "Xuens Zorn", ["text"] = "100 Meter Reichweite\nSofort\n'Comboschläge' gewähren Euch eine stapelbare Chance von 1%, dass Euer nächster Einsatz von 'Furorfäuste' Euch 10 Sek. lang 3% kritischen Trefferwert, Tempo und Meisterschaft gewährt und dabei Xuen den Weißen Tiger beschwört." }
