entries[396169] = { ["name"] = "Elementargeladener Stein", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nAufmerksame und neugierige Minenarbeiter entdecken manchmal geologische Proben, die von mehreren Elementen durchdrungen sind. Doch diese übrig gebliebenen Energien scheinen fest entschlossen zu sein, die Materialien, an denen sie sich festgeklammert haben, niemals loszulassen.\n\nEs wäre zwar unklug, sie zu stören, doch man könnte durch das Studieren der magischen Bindung vermutlich das ein oder andere lernen.\nBeruf:\nBergbau (1)" }
entries[396170] = { ["name"] = "Sonne tanken", ["text"] = "Unbegrenzte Reichweite\nSofort\nGeht sonnenbaden." }
entries[396171] = { ["name"] = "Aufgeladene Pollen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nWenn die Elementarenergien der Dracheninseln erwachen, verbinden sie sich mit allen möglichen Materialien. Fleißige Kräuterkundige können Pollen finden, an die sich diese Energien gebunden haben.\n\nEine solche Bindung zu stören, könnte sich zwar als gefährlich erweisen, doch durch das Studieren eines so seltenen Phänomens würdet Ihr wertvolles Wissen erlangen.\nBeruf:\nKräuterkunde der Dracheninseln (1)" }
entries[396172] = { ["name"] = "Gut gefälscht ist halb gewonnen", ["text"] = "Kanalisiert (Wirken in 5 sek.) 30 sek. Abklingzeit\nZeigt Euren Reichtum der Welt und hinterlässt eine Spur aus Reichtümern." }
entries[396173] = { ["name"] = "Gesättigter Knochen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Elemente, die auf den Dracheninseln erwachen, können sogar die dortige Fauna durchdringen. Fleißige Kürschner können Knochen finden, die von diesem seltene Phänomen besonders stark beeinflusst wurden.\n\nDas Studieren solcher Exemplare könnte sich in Form neuen Wissens als sehr vorteilhaft erweisen.\nBeruf:\nKürschnerei (1)" }
entries[396174] = { ["name"] = "Verbündetenhandgelenksschützer der Kameradschaft", ["text"] = "Sofort\nGewährt 4 Vielseitigkeit für jeden Verbündeten im Umkreis von 30 Metern. Bis zu 4-mal stapelbar." }
entries[396175] = { ["name"] = "Bindung der Bruthüterin", ["text"] = "Unbegrenzte Reichweite\nSofort\nAls fürsorgliche Pflegerin verbindet die Bruthüterin ihre Lebensessenz mit den unausgebrüteten Eiern und verhindert bei weniger als 2% verbleibender Gesundheit jeglichen Schaden. Dieser Effekt wird für jedes intakte Ei im Raum gestapelt.\n\nZusätzlich erhöht diese Aura den verursachten Schaden von Verbündeten in der Nähe um 50%, verringert ihren erlittenen Schaden um 25% und heilt sie pro Sekunde um 3% ihrer gesamten Gesundheit. Hält 5 Sek. lang an. Dieser Effekt ist stapelbar." }
entries[396176] = { ["name"] = "Sande der temporalen Perfektion", ["text"] = "Ca. 1 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine geringe Chance, in der Nähe Eurer Position eine Temporaltasche zu erschaffen, die 15 Sek. lang bestehen bleibt. Wenn Ihr innerhalb der Tasche steht, gewährt sie Euch 251 Tempo und 1063 Bewegungsgeschwindigkeit, die sich schnell wieder verringert.\n(500ms Abklingzeit)" }
entries[396177] = { ["name"] = "Bindung der Bruthüterin", ["text"] = "Unbegrenzte Reichweite\nSofort\nAls fürsorgliche Pflegerin verbindet die Bruthüterin ihre Lebensessenz mit den unausgebrüteten Eiern und verhindert bei weniger als 2% verbleibender Gesundheit jeglichen Schaden. Dieser Effekt wird für jedes intakte Ei im Raum gestapelt.\n\nZusätzlich erhöht diese Aura den verursachten Schaden von Verbündeten in der Nähe um 50%, verringert ihren erlittenen Schaden um 25% und heilt sie pro Sekunde um 3% ihrer gesamten Gesundheit. Hält 5 Sek. lang an. Dieser Effekt ist stapelbar." }
