entries[396278] = { ["name"] = "Vom Donner gerührt", ["text"] = "Unbegrenzte Reichweite\nSofort\nRaszageth markiert einen Spielercharakter und gewährt ihm um 25% erhöhte Bewegungsgeschwindigkeit sowie Immunität gegen Verlangsamungs- und Bewegungsunfähigkeitseffekte. Außerdem lässt Raszageth 3 Sek. lang alle 0.3 Sek. Blitze an der Position des Spielercharakters einschlagen.\n\nBlitzschläge fügen Spielercharakteren und Kreaturen innerhalb von 4 Metern um den Einschlagsbereich 25 Naturschaden zu und erhöhen ihren erlittenen Schaden 10 Sek. lang um 10%." }
