entries[396351] = { ["name"] = "Erfüllter Niederschlag", ["text"] = "Unbegrenzte Reichweite\nWirken in 1 sek.\nTerros schlägt auf den Boden und setzt alle Spielercharaktere einem instabilen Staub aus, der alle 1 Sek. 10599 Schaden verursacht.\n\nWenn sich zwei betroffene Spielercharaktere berühren, löst der schädliche Staub eine ' Explosive Reaktion ' aus." }
