entries[396361] = { ["name"] = "Kristallisieren", ["text"] = "300 Meter Reichweite\nSofort\nErzeugt eine Barriere um den Kristall herum, die 83021 Schaden absorbiert. Solange die Barriere besteht, wird alle 1 Sek. 1212225 Arkanschaden verursacht." }
entries[396362] = { ["name"] = "Samenbombe", ["text"] = "20 Meter Reichweite\nWirken in 1 sek. 18 sek. Abklingzeit\nStuns all enemies within 5 yards of the impact, rendering them unable to move or attack for 5 Sek..\nImmobilizes all enemies within 5 yards of the impact for 5 Sek.." }
entries[396363] = { ["name"] = "Donnernd", ["text"] = "Sofort\nRaszageth markiert einen Spielercharakter mit einem ' Mal des Windes ' oder ' Mal des Blitzes ', wodurch dessen verursachter Schaden und hervorgerufene Heilung 15 Sek. lang um 30% erhöht wird. Mit dem gegensätzlichen Mal in Kontakt zu kommen, neutralisiert den Effekt für beide Spielercharaktere.\n\nNach 15 Sek. erleiden die betroffenen Spielercharaktere eine ' Urzeitliche Überladung ', wodurch sie betäubt werden und 5 Sek. lang alle 1 Sek. 9 Naturschaden erleiden." }
entries[396364] = { ["name"] = "Mal des Windes", ["text"] = "Unbegrenzte Reichweite\nSofort\nErfüllt einen Spielercharakter mit urzeitlicher Kraft und erhöht dessen Schaden und Heilung 15 Sek. lang um 30%.\n\nWenn sich bei Ablauf innerhalb von 100 Metern ein Spielercharakter mit ' Mal des Blitzes ' befindet, wird ' Urzeitliche Überladung ' ausgelöst, betäubt die markierten Spielercharaktere für 5 Sek. und fügt ihnen währenddessen alle 1 Sek. 9 Naturschaden zu.\n\nDieser Effekt wird bei Kontakt mit einem ' Mal des Blitzes ' entfernt." }
entries[396365] = { ["name"] = "Explosive Reaktion" }
entries[396366] = { ["name"] = "Eisige Qual", ["text"] = "30 Meter Reichweite\nWirken in 2 sek. 2 sek. Abklingzeit\nReduces the movement speed of the target by 30% for 10 Sek..\nReduces attacking and casting speed by 10% for 10 Sek..\nInflicts 19 Frost damage to an enemy." }
entries[396367] = { ["name"] = "Toxischer Strahl", ["text"] = "Nahkampfreichweite\nWirken in 2.5 sek. 13 sek. Abklingzeit\nSchleudert die Fäulnis in Euch auf Gegner in einem kegelförmigen Bereich vor Euch, um 34 Naturschaden zu verursachen und getroffene Gegner um 30% zu verlangsamen." }
entries[396369] = { ["name"] = "Mal des Blitzes", ["text"] = "Unbegrenzte Reichweite\nSofort\nErfüllt einen Spielercharakter mit urzeitlicher Kraft und erhöht dessen Schaden und Heilung 15 Sek. lang um 30%.\n\nWenn sich bei Ablauf innerhalb von 100 Metern ein Spielercharakter mit ' Mal des Windes ' befindet, wird ' Urzeitliche Überladung ' ausgelöst, betäubt die markierten Spielercharaktere für 5 Sek. und fügt ihnen währenddessen alle 1 Sek. 9 Naturschaden zu.\n\nDieser Effekt wird bei Kontakt mit einem ' Mal des Windes ' entfernt." }
